create table wksp_dtesc.sgt_enlaces_fo (
    id                           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    nombre                       varchar2(255 byte) not null enable,
    sitio_id_a                   number,
    equipo_id_a                  number,
    sitio_id_b                   number,
    equipo_id_b                  number,
    "CERTIFICACIÓN"              number,
    unidad_medida                varchar2(3 byte),
    abs_longitud                 number,
    cantidad_de_pelos            number,
    tipo_de_fo                   varchar2(50 byte),
    tipo                         varchar2(50 byte) not null enable,
    lt                           varchar2(50 byte) not null enable,
    conector                     varchar2(50 byte),
    estado                       varchar2(50 byte) not null enable,
    comentarios                  varchar2(4000 byte),
    "PROYECTO_DE_IMPLEMENTACIÓN" varchar2(255 byte),
    "FECHA_IMPLEMENTACIÓN"       timestamp(9),
    unidad_encargada_actual      varchar2(255 byte),
    creado_por                   varchar2(255 byte),
    creado_el                    timestamp(9),
    actualizado_por              varchar2(255 byte),
    actualizado_el               timestamp(9),
    tipo_cable                   varchar2(255 byte),
    tipo_tendido                 varchar2(25 byte),
    puertos_lado_a               varchar2(255 byte),
    puertos_lado_b               varchar2(255 byte)
);

alter table wksp_dtesc.sgt_enlaces_fo
    add constraint chk_enlaces_fo_estado
        check ( estado in ( 'Activo', 'Cortado', 'Suprimido / Retirado', 'Desconocido', 'Planificado' ) ) enable;

alter table wksp_dtesc.sgt_enlaces_fo add primary key ( id )
    using index enable;


